function fewestCameras(root: TreeNode | null): number {
  const nodes: TreeNode[] = [], parent: number[] = [];
  const q: [TreeNode, number][] = [[root!, -1]];
  for (let h = 0; h < q.length; h++) {
    const [node, p] = q[h];
    nodes.push(node); parent.push(p);
    if (node.left) q.push([node.left, nodes.length - 1]);
    if (node.right) q.push([node.right, nodes.length - 1]);
  }
  const n = nodes.length;
  let best = n;
  for (let mask = 0; mask < 1 << n; mask++) {
    let bits = 0;
    for (let i = 0; i < n; i++) if (mask >> i & 1) bits++;
    if (bits >= best) continue;
    const seen = new Array(n).fill(false);
    for (let i = 0; i < n; i++) {
      if (!(mask >> i & 1)) continue;
      seen[i] = true;
      if (parent[i] >= 0) seen[parent[i]] = true;
    }
    for (let i = 0; i < n; i++) if (parent[i] >= 0 && (mask >> parent[i] & 1)) seen[i] = true;
    if (seen.every(Boolean)) best = bits;
  }
  return best;
}

