class Solution:
    def fewestCameras(self, root: Optional[TreeNode]) -> int:
        nodes, parent = [], []
        q = deque([(root, -1)])
        while q:
            node, p = q.popleft()
            nodes.append(node)
            parent.append(p)
            idx = len(nodes) - 1
            if node.left:
                q.append((node.left, idx))
            if node.right:
                q.append((node.right, idx))
        n = len(nodes)
        best = n
        for mask in range(1 << n):
            bits = bin(mask).count("1")
            if bits >= best:
                continue
            seen = [False] * n
            for i in range(n):
                p = parent[i]
                if mask >> i & 1:
                    seen[i] = True
                    if p >= 0:
                        seen[p] = True
                elif p >= 0 and mask >> p & 1:
                    seen[i] = True
            if all(seen):
                best = bits
        return best

