function fewestCameras(root: TreeNode | null): number {
  // [camera here, watched by a child, not watched but everything below is]
  const visit = (node: TreeNode | null): [number, number, number] => {
    if (!node) return [Infinity, 0, 0];
    const [la, lb, lc] = visit(node.left);
    const [ra, rb, rc] = visit(node.right);
    const cam = 1 + Math.min(la, lb, lc) + Math.min(ra, rb, rc);
    const byChild = Math.min(la + Math.min(ra, rb), ra + Math.min(la, lb));
    const open = lb + rb;
    return [cam, byChild, open];
  };
  const [a, b] = visit(root);
  return Math.min(a, b);
}

