function fewestCameras(root: TreeNode | null): number {
  let cameras = 0;
  // 0 = needs watching, 1 = has a camera, 2 = watched without a camera
  const visit = (node: TreeNode | null): number => {
    if (!node) return 2;
    const l = visit(node.left), r = visit(node.right);
    if (l === 0 || r === 0) { cameras++; return 1; }
    if (l === 1 || r === 1) return 2;
    return 0;
  };
  if (visit(root) === 0) cameras++;
  return cameras;
}

